
(function(){
var SRC={"w1": "data:image/webp;base64,", "w2": "data:image/webp;base64,", "w3": "data:image/webp;base64,", "w4": "data:image/webp;base64,", "w5": "data:image/webp;base64,", "w6": "data:image/webp;base64,", "w7": "data:image/webp;base64,", "w8": "data:image/webp;base64,", "w9": "data:image/webp;base64,", "w10": "data:image/webp;base64,", "w11": "data:image/webp;base64,", "w12": "data:image/webp;base64,", "w13": "data:image/webp;base64,", "w14": "data:image/webp;base64,", "w15": "data:image/webp;base64,", "w16": "data:image/webp;base64,", "g1": "data:image/webp;base64,", "g2": "data:image/webp;base64,", "g3": "data:image/webp;base64,", "g4": "data:image/webp;base64,", "g5": "data:image/webp;base64,", "g6": "data:image/webp;base64,", "g7": "data:image/webp;base64,", "g8": "data:image/webp;base64,", "g9": "data:image/webp;base64,", "g10": "data:image/webp;base64,", "g11": "data:image/webp;base64,", "g12": "data:image/webp;base64,", "h1": "data:image/webp;base64,", "h2": "data:image/webp;base64,", "h3": "data:image/webp;base64,", "h4": "data:image/webp;base64,", "h5": "data:image/webp;base64,", "h6": "data:image/webp;base64,", "h7": "data:image/webp;base64,", "h8": "data:image/webp;base64,"};
var NL=16,CYC=0.548,PACE=1.2,STOP=14.3;
var SEQ=[['g1',140],['g2',120],['g3',120],['g4',170],['g5',100],['g6',100],['g7',100],['g8',130],
 ['h1',105],['h2',105],['h3',105],['h4',105],['h5',105],['h6',105],['h7',105],['h8',105],['h1',105],['h2',105],['h3',105],['h4',105],['h5',105],['h6',105],['h7',105],['h8',105],['h1',130],
 ['g8',110],['g7',95],['g6',95],['g5',95],['g4',170],['g3',115],['g2',115],['g1',170]],HOLD=0;SEQ.forEach(function(q){HOLD+=q[1]});
var HI0=0,HI1=0;(function(){var t=0;SEQ.forEach(function(q,i){if(i===8)HI0=t;if(i===25)HI1=t;t+=q[1]})})();
var st={},stOn=false,FADE=55;
var box,hi,fr=[],raf=0;
function build(){box=document.createElement('div');box.id='drmWalk';box.setAttribute('aria-hidden','true');
  var s=document.createElement('div');s.className='dw-s';box.appendChild(s);
  for(var i=1;i<=NL;i++){var m=new Image();m.alt='';m.decoding='async';m.src=SRC['w'+i];fr.push(m);box.appendChild(m)}
  ['g1','g2','g3','g4','g5','g6','g7','g8','h1','h2','h3','h4','h5','h6','h7','h8'].forEach(function(k){var m=new Image();m.alt='';m.decoding='async';m.src=SRC[k];m.className='st';st[k]=m;box.appendChild(m)});
  hi=document.createElement('div');hi.className='dw-hi';hi.innerHTML='<span class="dwh-wv">&#x1F44B;</span><span class="dwh-tx"><b>Hi!</b><span>Keep it up!</span></span><i class="dwh-sk a">&#x2726;</i><i class="dwh-sk b">&#x2726;</i>';box.appendChild(hi);
  document.body.appendChild(box)}
function hideStills(){for(var k in st)st[k].style.opacity=0;stOn=false}
function seqAt(a){ /* a = ms into the hold */
  var j=0,r=a;while(j<SEQ.length-1&&r>=SEQ[j][1]){r-=SEQ[j][1];j++}
  var A=SEQ[j][0],B=j<SEQ.length-1?SEQ[j+1][0]:null,d=SEQ[j][1],t=B?Math.min(1,Math.max(0,(r-d*.5)/(d*.5))):0;t=t*t*(3-2*t);
  for(var k in st){var o=k===A?1:(k===B?t:0);if(B===A&&k===A)o=1;st[k].style.opacity=o;st[k].style.zIndex=k===B?21:20}
  /* fade in over the walking pose at the start, out at the end */
  var head=Math.min(1,a/FADE),tail=Math.min(1,(HOLD-a)/FADE);
  var m=Math.min(head,tail); if(m<1){for(var k2 in st)st[k2].style.opacity=String(parseFloat(st[k2].style.opacity)*m)}
  stOn=true; return m}
function pose(p){if(stOn)hideStills();var q=p*NL,i=Math.floor(q),f=q-i,a=((i%NL)+NL)%NL,b=(a+1)%NL,t=Math.min(1,Math.max(0,(f-.82)/.18));t=t*t*(3-2*t);
  for(var j=0;j<NL;j++){fr[j].style.opacity=j===a?1:(j===b?t:0);fr[j].style.zIndex=j===b?1:0}}
var walking=false;
function sig(k){try{document.dispatchEvent(new CustomEvent('drmwalk',{detail:k}))}catch(e){}}
function stop(){cancelAnimationFrame(raf);raf=0;if(walking){walking=false;sig('end')}if(box){box.classList.remove('on');hi.classList.remove('on');hideStills();box.style.transform='translate3d(-130%,0,0)'}}
function play(){
  if(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  if(!box)build(); stop();
  var r=box.getBoundingClientRect(),h=r.height||window.innerHeight*.25,bw=r.width||h*316/440,vw=window.innerWidth;
  var cyc=CYC*h,step=cyc/NL,v=cyc*PACE,xc=(vw-bw)/2;
  var need=xc+bw+10,D=Math.ceil((need-STOP*step)/cyc)*cyc+STOP*step,x0=xc-D;
  var Tin=D/v*1.06*1000,Dout=(vw+10)-xc,Tout=Dout/v*1.06*1000,t0=performance.now();
  walking=true;sig('start');box.classList.add('on');hi.style.marginLeft='0px';var over=xc+hi.offsetLeft+hi.offsetWidth-(vw-8);if(over>0)hi.style.marginLeft=(-over)+'px';
  function g(u){var a=.86;return u<a?u/a*(1-.07):(1-.07)+.07*(1-Math.pow(1-(u-a)/(1-a),2))}
  function gi(u){var a=.12;return u<a?.065*Math.pow(u/a,2):.065+(u-a)/(1-a)*.935}
  function frame(now){
    var t=Math.max(0,now-t0),x;
    if(t<Tin){var d=D*g(t/Tin);x=x0+d;pose(d/cyc)}
    else if(t<Tin+HOLD){x=xc;var a=t-Tin;pose(STOP/NL);var m=seqAt(a);if(m>=1)for(var j2=0;j2<NL;j2++)fr[j2].style.opacity=0;hi.classList.toggle('on',a>HI0&&a<HI1)}
    else if(t<Tin+HOLD+Tout){hi.classList.remove('on');var d2=Dout*gi((t-Tin-HOLD)/Tout);x=xc+d2;pose((d2+STOP*step)/cyc)}
    else{stop();return}
    box.style.transform='translate3d('+x.toFixed(1)+'px,0,0)';
    raf=requestAnimationFrame(frame)}
  raf=requestAnimationFrame(frame)}
document.addEventListener('plate',function(e){if(e.detail==='blueprint')play();else stop()});
(function first(){if(document.body.classList.contains('pre')){setTimeout(first,400);return}
  var s=document.querySelector('section.plate[data-id="blueprint"]');if(s&&!s.hidden)play()})();
window.drmWalkPlay=play;
})();
